81	     */
82	    public record ForwardMap(
83	            @NotNull Vec3i nOffset,
84	            @NotNull Vec3i eOffset,
85	            @NotNull Vec3i dOffset,
86	            int faceAxis,
87	            int tangentAxis
88	    ) {
89	        public boolean hasTangent() {
90	            return eOffset.getX() != 0 || eOffset.getY() != 0 || eOffset.getZ() != 0;
91	        }
92	    }
