161	    /**
162	     * Step size used inside a concrete octree node: {@code min(branchSize, stepForDistance)}, so a
163	     * real fine leaf still wins when the tree has subdivided below the frustum LOD.
164	     *
165	     * @param growthPerBlock precomputed rate, e.g. {@code PrecomputedConfig.pConfig.frustumGrowthPerBlock}
166	     */
167	    public static int effectiveStepSize(int branchSize, double distance, double growthPerBlock) {
168	        int branch = Math.max(1, branchSize);
169	        return Math.min(branch, stepForDistance(distance, growthPerBlock));
170	    }
