181	    /**
182	     * Unit axis of the hit face pointing with the ray (forward through the face). Cast stores
183	     * {@code plane = -sign(ray)} on the crossed axis; this recovers the travel sign.
184	     */
185	    public static @NotNull Vec3i forwardFace(@NotNull Vec3i face, @NotNull Vec3d rayDir) {
186	        int axis = faceAxis(face);
187	        int s = axisSign(component(rayDir, axis));
188	        if (s == 0) {
189	            int f = axis == 0 ? face.getX() : axis == 1 ? face.getY() : face.getZ();
190	            s = -Integer.signum(f);
191	            if (s == 0) {
192	                s = 1;
193	            }
194	        }
195	        return axisUnit(axis, s);
196	    }
