239	    /**
240	     * Next face plane the ray would exit after entering the same-size neighbor beyond
241	     * {@code firstAxis}/{@code firstTravelSign}. Does not sample the octree — only assumes a
242	     * {@code cellSize} cube abutting H. Plane uses Cast's {@code -sign(ray)} convention.
243	     */
244	    public static @Nullable Vec3i nextDdaPlane(
245	            @NotNull Vec3d cellBase,
246	            int cellSize,
247	            @NotNull Vec3d hitPos,
248	            @NotNull Vec3d rayDir,
249	            int firstAxis,
250	            int firstTravelSign
251	    ) {
252	        int s = Math.max(1, cellSize);
253	        if (firstTravelSign == 0) {
254	            return null;
255	        }
256	        double nextX = cellBase.x + (firstAxis == 0 ? firstTravelSign * s : 0);
257	        double nextY = cellBase.y + (firstAxis == 1 ? firstTravelSign * s : 0);
258	        double nextZ = cellBase.z + (firstAxis == 2 ? firstTravelSign * s : 0);
259	        return ddaExitPlane(nextX, nextY, nextZ, s, hitPos, rayDir);
260	    }
