262	    /**
263	     * Argmin axis exit from an AABB, matching {@code Cast.getStepPair}'s bound/tie rules. Plane
264	     * components are {@code -sign(dir)} on the winning axis.
265	     */
266	    static @Nullable Vec3i ddaExitPlane(
267	            double baseX, double baseY, double baseZ,
268	            int size,
269	            @NotNull Vec3d position,
270	            @NotNull Vec3d vector
271	    ) {
272	        double xstep = boundAxis(baseX, position.x, size, vector.x);
273	        double ystep = boundAxis(baseY, position.y, size, vector.y);
274	        double zstep = boundAxis(baseZ, position.z, size, vector.z);
275	
276	        boolean yWins = ystep < xstep;
277	        double coefficient = yWins ? ystep : xstep;
278	        int axis = yWins ? 1 : 0;
279	
280	        boolean zWins = zstep < coefficient;
281	        coefficient = zWins ? zstep : coefficient;
282	        axis = zWins ? 2 : axis;
283	
284	        if (!(coefficient > 0) || !Double.isFinite(coefficient)) {
285	            return null;
286	        }
287	        double dir = axis == 0 ? vector.x : axis == 1 ? vector.y : vector.z;
288	        int planeSign = dir > 0 ? -1 : dir < 0 ? 1 : 0;
289	        if (planeSign == 0) {
290	            return null;
291	        }
292	        return axisUnit(axis, planeSign);
293	    }
