295	    /** Same positive-forward bound as {@code Cast.boundAxis}. */
296	    static double boundAxis(double base, double pos, double size, double dir) {
297	        double value = (base - pos + (dir > 0 ? size : 0)) / dir;
298	        if (value <= 0 || Double.isNaN(value)) {
299	            return Double.POSITIVE_INFINITY;
300	        }
301	        return value;
302	    }
