389	    /**
390	     * Moves a face-hit bounce origin according to {@code interaction}:
391	     * <ul>
392	     *   <li>{@link Interaction#CORNER} / {@link Interaction#SPLIT} — lerp toward H's shared
393	     *       leading vertex (same-sign tangents as {@code rayDir})</li>
394	     *   <li>{@link Interaction#FACE} — stay on the hit face and lerp along the leading tangent
395	     *       past H to the vertex shared only by D and E (one cell beyond H's leading edge)</li>
396	     *   <li>{@link Interaction#GAP} — stay on the occupied face, no walk</li>
397	     * </ul>
398	     * The occupied face is the nearer of the cell's two faces on the hit axis (the hit is
399	     * already on one of them).
400	     */
401	    public static @NotNull Vec3d edgeWalk(
402	            @NotNull Vec3d hit,
403	            @NotNull Vec3d cellBase,
404	            int cellSize,
405	            @NotNull Vec3i face,
406	            @NotNull Vec3d rayDir,
407	            double amount,
408	            @NotNull Interaction interaction
409	    ) {
410	        double minX = cellBase.x;
411	        double minY = cellBase.y;
412	        double minZ = cellBase.z;
413	        double maxX = minX + cellSize;
414	        double maxY = minY + cellSize;
415	        double maxZ = minZ + cellSize;
416	
417	        double x = hit.x;
418	        double y = hit.y;
419	        double z = hit.z;
420	
421	        if (face.getX() != 0) {
422	            x = nearer(hit.x, minX, maxX);
423	        } else if (face.getY() != 0) {
424	            y = nearer(hit.y, minY, maxY);
425	        } else if (face.getZ() != 0) {
426	            z = nearer(hit.z, minZ, maxZ);
427	        }
428	
429	        if (interaction == Interaction.GAP) {
430	            return new Vec3d(x, y, z);
431	        }
432	
433	        double t = Math.max(0.0, Math.min(1.0, amount));
434	        if (interaction == Interaction.FACE) {
435	            // Along the wall to the D–E-only vertex: primary tangent past H by one cell.
436	            int faceAxis = face.getX() != 0 ? 0 : face.getY() != 0 ? 1 : 2;
437	            int a1 = (faceAxis + 1) % 3;
438	            int a2 = (faceAxis + 2) % 3;
439	            double r1 = component(rayDir, a1);
440	            double r2 = component(rayDir, a2);
441	            int tangentAxis = Math.abs(r1) >= Math.abs(r2) ? a1 : a2;
442	            if (tangentAxis == 0) {
443	                x = walkAxisPast(x, minX, maxX, rayDir.x, cellSize, t);
444	            } else if (tangentAxis == 1) {
445	                y = walkAxisPast(y, minY, maxY, rayDir.y, cellSize, t);
446	            } else {
447	                z = walkAxisPast(z, minZ, maxZ, rayDir.z, cellSize, t);
448	            }
449	            return new Vec3d(x, y, z);
450	        }
451	
452	        // CORNER / SPLIT: H's leading vertex.
453	        if (face.getX() != 0) {
454	            y = walkAxis(y, minY, maxY, rayDir.y, t);
455	            z = walkAxis(z, minZ, maxZ, rayDir.z, t);
456	        } else if (face.getY() != 0) {
457	            x = walkAxis(x, minX, maxX, rayDir.x, t);
458	            z = walkAxis(z, minZ, maxZ, rayDir.z, t);
459	        } else if (face.getZ() != 0) {
460	            x = walkAxis(x, minX, maxX, rayDir.x, t);
461	            y = walkAxis(y, minY, maxY, rayDir.y, t);
462	        }
463	        return new Vec3d(x, y, z);
464	    }
465	
466	    /** Corner walk (legacy default). Prefer the overload that takes {@link Interaction}. */
467	    public static @NotNull Vec3d edgeWalk(
468	            @NotNull Vec3d hit,
469	            @NotNull Vec3d cellBase,
470	            int cellSize,
471	            @NotNull Vec3i face,
472	            @NotNull Vec3d rayDir,
473	            double amount
474	    ) {
475	        return edgeWalk(hit, cellBase, cellSize, face, rayDir, amount, Interaction.CORNER);
476	    }
477	
478	    /**
479	     * Cast plane ({@code -sign(ray)} on the crossed axis) for a hit that already lies on a face of
480	     * {@code [cellBase, cellBase+cellSize]}. Corner/edge hits prefer the candidate axis with the
481	     * largest {|ray|} so the known exit matches DDA intent.
482	     */
483	    public static @NotNull Vec3i castPlaneAtHit(
484	            @NotNull Vec3d hit,
485	            @NotNull Vec3d cellBase,
486	            int cellSize,
487	            @NotNull Vec3d rayDir
488	    ) {
489	        int s = Math.max(1, cellSize);
490	        double maxX = cellBase.x + s;
491	        double maxY = cellBase.y + s;
492	        double maxZ = cellBase.z + s;
493	        final double eps = 1e-5;
494	        int bestAxis = -1;
495	        double bestAbs = -1.0;
496	        if (Math.abs(hit.x - cellBase.x) <= eps || Math.abs(hit.x - maxX) <= eps) {
497	            double a = Math.abs(rayDir.x);
498	            if (a >= bestAbs) {
499	                bestAbs = a;
500	                bestAxis = 0;
501	            }
502	        }
503	        if (Math.abs(hit.y - cellBase.y) <= eps || Math.abs(hit.y - maxY) <= eps) {
504	            double a = Math.abs(rayDir.y);
505	            if (a >= bestAbs) {
506	                bestAbs = a;
507	                bestAxis = 1;
508	            }
509	        }
510	        if (Math.abs(hit.z - cellBase.z) <= eps || Math.abs(hit.z - maxZ) <= eps) {
511	            double a = Math.abs(rayDir.z);
512	            if (a >= bestAbs) {
513	                bestAxis = 2;
514	            }
515	        }
516	        if (bestAxis < 0) {
517	            Vec3i face = dominantExitFace(rayDir);
518	            return new Vec3i(-face.getX(), -face.getY(), -face.getZ());
519	        }
520	        double dir = component(rayDir, bestAxis);
521	        int planeSign = dir > 0 ? -1 : dir < 0 ? 1 : 0;
522	        if (planeSign == 0) {
523	            // Hit is on a face but ray is parallel — use which side of the cell the hit sits on.
524	            double min = bestAxis == 0 ? cellBase.x : bestAxis == 1 ? cellBase.y : cellBase.z;
525	            double max = min + s;
526	            double h = component(hit, bestAxis);
527	            planeSign = Math.abs(h - max) <= eps ? -1 : 1;
528	        }
529	        return axisUnit(bestAxis, planeSign);
530	    }
531	
532	    /** Unit face along the largest {|component|} of {@code dir} (forward through that face). */
533	    public static @NotNull Vec3i dominantExitFace(@NotNull Vec3d dir) {
534	        double ax = Math.abs(dir.x);
535	        double ay = Math.abs(dir.y);
536	        double az = Math.abs(dir.z);
537	        if (ax >= ay && ax >= az) {
538	            return new Vec3i(dir.x >= 0 ? 1 : -1, 0, 0);
539	        }
540	        if (ay >= az) {
541	            return new Vec3i(0, dir.y >= 0 ? 1 : -1, 0);
542	        }
543	        return new Vec3i(0, 0, dir.z >= 0 ? 1 : -1);
544	    }
545	
546	    private static double walkAxis(double hit, double min, double max, double ray, double t) {
547	        if (ray > AXIS_EPS) {
548	            return lerp(hit, max, t);
549	        }
550	        if (ray < -AXIS_EPS) {
551	            return lerp(hit, min, t);
552	        }
553	        return hit;
554	    }
555	
556	    /** Leading edge of H, then one more {@code cellSize} into E/D (D–E-only vertex). */
557	    private static double walkAxisPast(double hit, double min, double max, double ray, int cellSize, double t) {
558	        if (ray > AXIS_EPS) {
559	            return lerp(hit, max + cellSize, t);
560	        }
561	        if (ray < -AXIS_EPS) {
562	            return lerp(hit, min - cellSize, t);
563	        }
564	        return hit;
565	    }
566	
567	    private static double nearer(double v, double a, double b) {
568	        return Math.abs(v - a) <= Math.abs(v - b) ? a : b;
569	    }
570	
571	    private static double lerp(double a, double b, double t) {
572	        return a + (b - a) * t;
573	    }
574	
575	    private static double component(Vec3d v, int axis) {
576	        return axis == 0 ? v.x : axis == 1 ? v.y : v.z;
577	    }
578	
579	    private static int axisSign(double v) {
580	        if (v > AXIS_EPS) {
581	            return 1;
582	        }
583	        if (v < -AXIS_EPS) {
584	            return -1;
585	        }
586	        return 0;
587	    }
588	
589	    private static Vec3i axisUnit(int axis, int signed) {
590	        return switch (axis) {
591	            case 0 -> new Vec3i(signed, 0, 0);
592	            case 1 -> new Vec3i(0, signed, 0);
593	            default -> new Vec3i(0, 0, signed);
594	        };
595	    }
596	}
